// Gruplu tablonun saf süzme mantığı: Türkçe harfe duyarsız arama, grup başına eşleşme sayısı. React içermez; test doğrudan bunu okur.
import { text } from "@snn/abacus-core";

export interface TableGroup<T> { key: string; title: string; rows: T[] }
export interface FilteredGroup<T> extends TableGroup<T> { total: number }

/**
 * Sorgudaki her kelime satır metninde geçiyorsa satır kalır ("istanbul" "İstanbul"u bulur).
 * Sorgu boşsa gruplar olduğu gibi döner. Sorgu varken eşleşmesi olmayan grup listeden düşer.
 */
export function filterGroups<T>(groups: TableGroup<T>[], query: string, searchText: (row: T) => string): { groups: FilteredGroup<T>[]; matches: number } {
  const words = text.searchKey(query.trim()).split(/\s+/).filter(Boolean);
  if (!words.length) return { groups: groups.map(group => ({ ...group, total: group.rows.length })), matches: groups.reduce((sum, group) => sum + group.rows.length, 0) };
  let matches = 0;
  const result: FilteredGroup<T>[] = [];
  for (const group of groups) {
    const rows = group.rows.filter(row => { const key = text.searchKey(searchText(row)); return words.every(word => key.includes(word)); });
    matches += rows.length;
    if (rows.length) result.push({ ...group, rows, total: group.rows.length });
  }
  return { groups: result, matches };
}

/* Sıralanabilir tabloyla aynı görünüm: kenar, köşe, satır yüksekliği ve başlık yazısı aynı değişkenlerden. */
.wrapper { container-type: inline-size; width: 100%; min-width: 0; overflow: hidden; border: 1px solid var(--border); border-radius: var(--radius-control); background: var(--surface); color: var(--foreground); }
.table { width: 100%; table-layout: fixed; border-collapse: separate; border-spacing: 0; font-size: var(--text-sm); line-height: var(--leading-body); letter-spacing: var(--tracking-body); text-align: left; }
.srOnly { position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.chevronCol { width: 40px; }
.table thead th { height: 44px; padding: 0 var(--space-4); border-bottom: 1px solid var(--border); color: var(--text-muted); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.table thead th:first-child { padding: 0; }
.table td { height: 48px; padding: var(--space-2) var(--space-4); border-bottom: 1px solid var(--border-subtle); vertical-align: middle; overflow-wrap: anywhere; }
.table td:first-child { padding: 0; }
.table [data-numeric] { text-align: right; font-variant-numeric: tabular-nums; }
.table tbody:last-of-type tr:last-child td, .table tbody:last-of-type:not([data-expanded]) th { border-bottom: 0; }

/* Grup başlığı tam genişlik bir düğmedir: ok, ad, sayı ve durum rozeti. */
.groupRow th { padding: 0; border-bottom: 1px solid var(--border-subtle); background: color-mix(in oklab, var(--surface-muted) 55%, var(--surface)); font-weight: 400; }
.groupButton { display: flex; width: 100%; min-height: 48px; align-items: center; gap: var(--space-2); border: 0; padding: 0 var(--space-4) 0 var(--space-3); background: transparent; color: var(--foreground); font: inherit; text-align: left; cursor: pointer; transition: background-color var(--duration-fast) var(--ease-standard); }
.groupButton[aria-disabled] { cursor: default; }
@media (hover: hover) and (pointer: fine) { .groupButton:not([aria-disabled]):hover { background: var(--surface-muted); } }
.chevron { display: inline-flex; flex: none; color: var(--text-muted); }
.groupTitle { min-width: 0; font-weight: 500; overflow-wrap: anywhere; }
.count { flex: none; border: 1px solid var(--border-subtle); border-radius: var(--radius-pill); padding: 1px 8px; background: var(--surface); color: var(--text-secondary); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.status { --tone: var(--text-secondary); flex: none; margin-left: auto; border-radius: var(--radius-pill); padding: 2px 9px; background: color-mix(in oklab, var(--tone) 11%, transparent); color: var(--tone); font-size: var(--text-xs); }
.status[data-tone="success"] { --tone: var(--success); }
.status[data-tone="warning"] { --tone: var(--warning); }
.status[data-tone="danger"] { --tone: var(--danger); }
.summary { margin: 0; padding: var(--space-2) var(--space-4); border-bottom: 1px solid var(--border-subtle); color: var(--text-secondary); font-size: var(--text-xs); }
.empty { margin: 0; padding: var(--space-6) var(--space-4); color: var(--text-muted); font-size: var(--text-sm); text-align: center; }

/* Dar kap: isteğe bağlı sütunlar gizlenir, tablo yana kaymaz. */
@container (max-width: 36rem) {
  /* Sabit sütun genişlikleri bırakılır; kalan sütunlar içeriğe göre paylaşır, gizlenen sütun yer tutmaz. */
  .table { table-layout: auto; }
  .table col { width: auto !important; }
  .table col.chevronCol { width: 32px !important; }
  .table [data-optional] { display: none; }
  .table td, .table thead th { padding-inline: var(--space-2); }
  .table td { overflow-wrap: normal; word-break: normal; }
  .table [data-numeric] { white-space: nowrap; }
}
@media (prefers-reduced-motion: reduce) { .groupButton { transition: none; } }

"use client";

import { useId, useState, type ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ChevronRight } from "lucide-react";
import { motionTokens } from "../lib/motion-tokens";
import { filterGroups, type TableGroup } from "./grouped-table-filter";
import styles from "./grouped-table.module.css";

export interface GroupedTableColumn<T> {
  key: string;
  header: string;
  /** Hücre içeriği. Verilmezse satırın `key` alanı düz metin yazılır. */
  render?: ((row: T) => ReactNode) | undefined;
  /** Sayı sütunu: sağa yaslı, eşit genişlikli rakam. */
  numeric?: boolean | undefined;
  /** Dar kapta (36rem altı) gizlenir; tablo yana kaymaz. */
  optional?: boolean | undefined;
  /** Sütun genişliği, örneğin "30%" ya da "8rem". */
  width?: string | undefined;
}

export interface GroupedTableGroup<T> extends TableGroup<T> {
  /** Grup başlığındaki durum rozeti, örneğin { tone: "danger", label: "2 hata" }. Uyarı tonu mavi-gridir. */
  status?: { tone: "success" | "warning" | "danger" | "neutral"; label: string } | undefined;
}

export interface GroupedTableProps<T> {
  groups: GroupedTableGroup<T>[];
  columns: GroupedTableColumn<T>[];
  rowKey: (row: T) => string;
  /** Tabloyu yardımcı teknolojiye adlandırır. */
  caption: string;
  /** Arama metni. Doluyken eşleşen satırlar kalır ve gruplar zorla açılır. */
  query?: string | undefined;
  /** Aramada satırın hangi metne bakılacağı. Varsayılan: satırdaki bütün metin ve sayı alanları. */
  searchText?: ((row: T) => string) | undefined;
  /** Başta açık grupların anahtarları; "all" hepsini açar. Varsayılan: hepsi kapalı. */
  defaultExpanded?: string[] | "all" | undefined;
  emptyMessage?: string | undefined;
  className?: string | undefined;
}

const allText = (row: unknown) => typeof row === "object" && row ? Object.values(row).filter(value => typeof value === "string" || typeof value === "number").join(" ") : String(row);

/** Satırları gruplara bölen tablo: her grup bir <tbody>, başlığı açılıp kapanan düğmedir. Arama varken gruplar açılır. */
export function GroupedTable<T>({ groups, columns, rowKey, caption, query = "", searchText = allText, defaultExpanded, emptyMessage = "Aramaya uyan satır yok.", className }: GroupedTableProps<T>) {
  const id = useId();
  const reduce = !!useReducedMotion();
  const [open, setOpen] = useState<Set<string>>(() => new Set(defaultExpanded === "all" ? groups.map(group => group.key) : defaultExpanded ?? []));
  const searching = query.trim().length > 0;
  const filtered = filterGroups(groups, query, searchText);
  const statusOf = new Map(groups.map(group => [group.key, group.status]));
  const toggle = (key: string) => setOpen(current => { const next = new Set(current); if (next.has(key)) next.delete(key); else next.add(key); return next; });
  return <div className={[styles.wrapper, className].filter(Boolean).join(" ")}>
    {searching && <p className={styles.summary} role="status">{filtered.matches} satır eşleşti</p>}
    <table className={styles.table}>
      <caption className={styles.srOnly}>{caption}</caption>
      <colgroup><col className={styles.chevronCol} />{columns.map(column => <col key={column.key} data-optional={column.optional || undefined} style={column.width ? { width: column.width } : undefined} />)}</colgroup>
      <thead><tr><th scope="col"><span className={styles.srOnly}>Aç ya da kapat</span></th>{columns.map(column => <th key={column.key} scope="col" data-numeric={column.numeric || undefined} data-optional={column.optional || undefined}>{column.header}</th>)}</tr></thead>
      {filtered.groups.map(group => {
        const expanded = searching || open.has(group.key);
        const status = statusOf.get(group.key);
        const rowsId = `${id}-${group.key}`;
        return <tbody key={group.key} data-expanded={expanded || undefined}>
          <tr className={styles.groupRow}>
            <th scope="rowgroup" colSpan={columns.length + 1}>
              <button type="button" className={styles.groupButton} aria-expanded={expanded} aria-controls={expanded ? rowsId : undefined} aria-disabled={searching || undefined} onClick={() => { if (!searching) toggle(group.key); }}>
                <motion.span className={styles.chevron} initial={false} animate={{ rotate: expanded ? 90 : 0 }} transition={reduce ? { duration: 0 } : motionTokens.spring.snappy} aria-hidden="true"><ChevronRight size={16} strokeWidth={1.75} /></motion.span>
                <span className={styles.groupTitle}>{group.title}</span>
                <span className={styles.count} aria-label={searching ? `${group.total} satırdan ${group.rows.length} eşleşme` : `${group.total} satır`}>{searching ? `${group.rows.length} / ${group.total}` : group.total}</span>
                {status && <span className={styles.status} data-tone={status.tone}>{status.label}</span>}
              </button>
            </th>
          </tr>
          {expanded && group.rows.map((row, index) => <tr key={rowKey(row)} id={index === 0 ? rowsId : undefined}>
            <td aria-hidden="true" />
            {columns.map(column => <td key={column.key} data-numeric={column.numeric || undefined} data-optional={column.optional || undefined}>{column.render ? column.render(row) : String((row as Record<string, unknown>)[column.key] ?? "")}</td>)}
          </tr>)}
        </tbody>;
      })}
    </table>
    {searching && filtered.groups.length === 0 && <p className={styles.empty}>{emptyMessage}</p>}
  </div>;
}

export default GroupedTable;
